def count_islands(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not seen[r][c]:
                count += 1
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if not (0 <= cr < rows and 0 <= cc < cols):
                        continue
                    if grid[cr][cc] != 1 or seen[cr][cc]:
                        continue
                    seen[cr][cc] = True
                    stack.extend([
                        (cr + 1, cc),
                        (cr - 1, cc),
                        (cr, cc + 1),
                        (cr, cc - 1),
                    ])

    return count
```

